export interface P { readonly x: number; readonly z: number }

export interface Mob extends P {
  readonly id: number;
  readonly kind: Archetype;
  readonly leak: number;
  readonly hp: number;
  readonly phase: Phase;
  readonly phaseT: number;
  readonly provoked: boolean;
  readonly targetX?: number;
  readonly targetZ?: number;
}

export interface Bolt extends P {
  readonly id: number;
  readonly from: number;
  readonly vx: number;
  readonly vz: number;
  readonly life: number;
  readonly damage: number;
}

export interface Leak extends P {
  readonly id: number;
  readonly kinds: readonly Archetype[];
  readonly seal: number;
  readonly sealed: boolean;
  readonly nextWave: number;
}

export interface World {
  readonly t: number;
  readonly rng: number;
  readonly nextId: number;
  readonly mobs: readonly Mob[];
  readonly bolts: readonly Bolt[];
  readonly leaks: readonly Leak[];
}

/**
 * A built footprint on the ground: an oriented box. Its centre is (x, z), its u axis is (ux, uz) (a unit vector), its v axis
 * is (-uz, ux), and hu and hv are its half sizes along each. Ground monsters keep out of it (P0-MON-03): a monster of
 * radius r stands no closer than r to any box.
 */
export interface Solid { readonly x: number; readonly z: number; readonly ux: number; readonly uz: number; readonly hu: number; readonly hv: number }

export interface Input {
  readonly dt: number;
  readonly stage: number;
  readonly aggression: Aggression;
  readonly player: P & { readonly alive: boolean };
  /** A machine's `hu` is its footprint's half size: a sapper drains it from the footprint's edge, not its centre. */
  readonly machines: readonly (P & { readonly id: number; readonly hu?: number })[];
  readonly safe: readonly (P & { readonly r: number })[];
  readonly sealing: number | null;
  readonly walkable?: (x: number, z: number) => boolean;
  /** The built footprints the ground monsters stay out of. */
  readonly solids?: readonly Solid[];
  /** Optional world-aligned navigation grid from `navFor(base, center)` for wall pathfinding (POL-32). */
  readonly nav?: NavGrid;
  /** The most living monsters this frame (the graphics budget); defaults to MAX_MOBS. */
  readonly cap?: number;
}

/** Whether a ground monster of radius r at (x, z) would stand inside a solid (its box grown by r). */
export function insideSolid(x: number, z: number, r: number, solids: readonly Solid[]): boolean {
  for (const s of solids) {
    const dx = x - s.x, dz = z - s.z;
    const du = dx * s.ux + dz * s.uz;
    const dv = -dx * s.uz + dz * s.ux;
    if (Math.abs(du) < s.hu + r && Math.abs(dv) < s.hv + r) return true;
  }
  return false;
}

/**
 * Pushes a ground monster out of the solids it stands in: each box it is inside moves it to the nearest edge of that box
 * (grown by r). Two passes, so a spot between two boxes settles too. A point clear of every box is returned unchanged.
 */
export function pushOutOfSolids(x: number, z: number, r: number, solids: readonly Solid[]): { readonly x: number; readonly z: number } {
  let cx = x, cz = z;
  for (let pass = 0; pass < 2; pass++) {
    for (const s of solids) {
      const dx = cx - s.x, dz = cz - s.z;
      const du = dx * s.ux + dz * s.uz;
      const dv = -dx * s.uz + dz * s.ux;
      const eu = s.hu + r, ev = s.hv + r;
      if (Math.abs(du) >= eu || Math.abs(dv) >= ev) continue;
      // the four exits: out along +u, -u, +v or -v, each at the grown edge
      const exits = [
        { d: eu - du, nu: eu, nv: dv },
        { d: eu + du, nu: -eu, nv: dv },
        { d: ev - dv, nu: du, nv: ev },
        { d: ev + dv, nu: du, nv: -ev },
      ];
      let best = exits[0]!;
      for (const e of exits) if (e.d < best.d) best = e;
      cx = s.x + best.nu * s.ux - best.nv * s.uz;
      cz = s.z + best.nu * s.uz + best.nv * s.ux;
    }
  }
  return { x: cx, z: cz };
}

export type Event =
  | { readonly t: 'warn'; readonly leak: number; readonly inSeconds: number }
  | { readonly t: 'spawn'; readonly mob: number; readonly leak: number }
  | { readonly t: 'telegraph'; readonly mob: number }
  | { readonly t: 'hitPlayer'; readonly mob: number; readonly damage: number }
  | { readonly t: 'drain'; readonly mob: number; readonly machine: number; readonly amount: number }
  | { readonly t: 'death'; readonly mob: number; readonly drop: Drop }
  | { readonly t: 'sealed'; readonly leak: number };

export const WARN_SECONDS = 20 as const;
export const SEAL_SECONDS = 6 as const;
export const MAX_MOBS = 24 as const;

function nextRng(state: number): { readonly value: number; readonly nextState: number } {
  const s = (state + 0x6D2B79F5) | 0;
  let t = Math.imul(s ^ (s >>> 15), 1 | s);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  const value = ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  return { value, nextState: s };
}

export function createWorld(seed: number): World {
  return {
    t: 0,
    rng: (seed | 0) >>> 0,
    nextId: 1,
    mobs: [],
    bolts: [],
    leaks: [],
  };
}

export function addLeak(w: World, at: P, kinds: readonly Archetype[]): World {
  const newLeak: Leak = {
    id: w.nextId,
    x: at.x,
    z: at.z,
    kinds: [...kinds],
    seal: 0,
    sealed: false,
    nextWave: w.t + WARN_SECONDS,
  };
  return {
    t: w.t,
    rng: w.rng,
    nextId: w.nextId + 1,
    mobs: w.mobs,
    bolts: w.bolts,
    leaks: [...w.leaks, newLeak],
  };
}

function waveInterval(aggression: Aggression): number {
  if (aggression === 'hard') return 60;
  if (aggression === 'calm') return 120;
  return 90;
}

function clampOutsideSafe(
  x: number,
  z: number,
  safe: readonly (P & { readonly r: number })[]
): { readonly x: number; readonly z: number } {
  if (safe.length === 0) return { x, z };
  let cx = x;
  let cz = z;
  for (let i = 0; i < safe.length; i++) {
    const s = safe[i];
    if (!s) continue;
    const dx = cx - s.x;
    const dz = cz - s.z;
    const distSq = dx * dx + dz * dz;
    const rSq = s.r * s.r;
    if (distSq < rSq) {
      const dist = Math.sqrt(distSq);
      if (dist > 1e-6) {
        cx = s.x + (dx / dist) * s.r;
        cz = s.z + (dz / dist) * s.r;
      } else {
        cx = s.x + s.r;
        cz = s.z;
      }
    }
  }
  return { x: cx, z: cz };
}

function isValidPosition(
  x: number,
  z: number,
  flies: boolean,
  safe: readonly (P & { readonly r: number })[],
  walkable?: (x: number, z: number) => boolean
): boolean {
  if (safe.length === 0 && (flies || !walkable)) return true;
  for (let i = 0; i < safe.length; i++) {
    const s = safe[i];
    if (!s) continue;
    const dx = x - s.x;
    const dz = z - s.z;
    if (dx * dx + dz * dz < s.r * s.r - 1e-7) return false;
  }
  if (!flies && walkable && !walkable(x, z)) return false;
  return true;
}

const TURN_OFFSETS = [0, 0.26, -0.26, 0.52, -0.52, 0.78, -0.78, 1.05, -1.05, 1.3, -1.3, 1.57, -1.57];

function steerGround(
  curX: number,
  curZ: number,
  baseAngle: number,
  dist: number,
  safe: readonly (P & { readonly r: number })[],
  walkable?: (x: number, z: number) => boolean,
  solids: readonly Solid[] = [],
  radius = 0
): { readonly x: number; readonly z: number } {
  for (let k = 0; k < TURN_OFFSETS.length; k++) {
    const offset = TURN_OFFSETS[k] ?? 0;
    const angle = baseAngle + offset;
    const candX = curX + Math.cos(angle) * dist;
    const candZ = curZ + Math.sin(angle) * dist;

    const clamped = clampOutsideSafe(candX, candZ, safe);
    if (isValidPosition(clamped.x, clamped.z, false, safe, walkable) && !insideSolid(clamped.x, clamped.z, radius, solids)) {
      return clamped;
    }
  }
  return { x: curX, z: curZ };
}

export function step(
  w: World,
  input: Input
): { readonly world: World; readonly events: readonly Event[] } {
  let curRng = w.rng;
  const rand = (): number => {
    const res = nextRng(curRng);
    curRng = res.nextState;
    return res.value;
  };

  let nextId = w.nextId;
  const events: Event[] = [];
  const dt = input.dt;
  const curT = w.t;
  const nextT = curT + dt;

  // 1. Process Leaks (Sealing, Waves, Warnings)
  const currentInterval = waveInterval(input.aggression);
  const updatedLeaks: Leak[] = [];
  const waveSpawnsToRun: { readonly leak: Leak; readonly kinds: readonly Archetype[] }[] = [];

  for (let i = 0; i < w.leaks.length; i++) {
    const l = w.leaks[i];
    if (!l) continue;

    let seal = l.seal;
    let sealed = l.sealed;
    let nextWave = l.nextWave;

    // The first wave is already scheduled at creationT + WARN_SECONDS

    if (!sealed) {
      const isSealing =
        input.sealing === l.id &&
        Math.hypot(input.player.x - l.x, input.player.z - l.z) <= 25;

      if (isSealing) {
        seal += dt / SEAL_SECONDS;
      } else {
        seal -= (dt / SEAL_SECONDS) * 0.5;
      }

      if (seal >= 1) {
        seal = 1;
        sealed = true;
        events.push({ t: 'sealed', leak: l.id });
      } else if (seal < 0) {
        seal = 0;
      }
    }

    if (!sealed) {
      if (input.aggression === 'off') {
        nextWave += dt;
      } else {
        const warnTime = nextWave - WARN_SECONDS;
        if (l.kinds.length > 0 && warnTime >= curT - 1e-7 && warnTime < nextT - 1e-7) {
          events.push({ t: 'warn', leak: l.id, inSeconds: WARN_SECONDS });
        }

        if (nextWave >= curT - 1e-7 && nextWave < nextT - 1e-7) {
          waveSpawnsToRun.push({ leak: l, kinds: l.kinds });
          nextWave += currentInterval;
        }
      }
    }

    updatedLeaks.push({
      id: l.id,
      x: l.x,
      z: l.z,
      kinds: l.kinds,
      seal,
      sealed,
      nextWave,
    });
  }

  // 2. Wave Spawning
  let livingMobsCount = 0;
  for (let i = 0; i < w.mobs.length; i++) {
    const m = w.mobs[i];
    if (m && m.phase !== 'dead') livingMobsCount++;
  }

  const newMobs: Mob[] = [];

  for (let wIdx = 0; wIdx < waveSpawnsToRun.length; wIdx++) {
    const waveInfo = waveSpawnsToRun[wIdx];
    if (!waveInfo) continue;
    const leak = waveInfo.leak;

    for (let kIdx = 0; kIdx < waveInfo.kinds.length; kIdx++) {
      const kind = waveInfo.kinds[kIdx];
      if (!kind) continue;
      const spec = ARCHETYPES[kind];
      const baseCount = spec.pack * (1 + Math.floor(input.stage / 2));
      const rawCount = input.aggression === 'hard' ? baseCount * 1.5 : baseCount;
      const count = Math.floor(rawCount);

      for (let c = 0; c < count; c++) {
        if (livingMobsCount >= (input.cap ?? MAX_MOBS)) break;

        let spawnX = leak.x;
        let spawnZ = leak.z;
        let found = false;

        for (let attempt = 0; attempt < 40; attempt++) {
          const r = Math.sqrt(rand()) * 5.8;
          const th = rand() * Math.PI * 2;
          const cx = leak.x + Math.cos(th) * r;
          const cz = leak.z + Math.sin(th) * r;

          const distP = Math.hypot(cx - input.player.x, cz - input.player.z);
          if (distP < 8.0) continue;

          let insideSafe = false;
          for (let sIdx = 0; sIdx < input.safe.length; sIdx++) {
            const s = input.safe[sIdx];
            if (!s) continue;
            if (Math.hypot(cx - s.x, cz - s.z) < s.r) {
              insideSafe = true;
              break;
            }
          }
          if (insideSafe) continue;

          if (!spec.flies && input.walkable && !input.walkable(cx, cz)) {
            continue;
          }

          spawnX = cx;
          spawnZ = cz;
          found = true;
          break;
        }

        if (!found) {
          const radii = [5.8, 5.0, 4.0, 3.0, 2.0, 1.0];
          const angles = 16;
          for (let rIdx = 0; rIdx < radii.length && !found; rIdx++) {
            const rad = radii[rIdx] ?? 5.0;
            for (let aIdx = 0; aIdx < angles; aIdx++) {
              const th = (aIdx / angles) * Math.PI * 2;
              const cx = leak.x + Math.cos(th) * rad;
              const cz = leak.z + Math.sin(th) * rad;

              if (Math.hypot(cx - input.player.x, cz - input.player.z) < 8.0) continue;

              let insideSafe = false;
              for (let sIdx = 0; sIdx < input.safe.length; sIdx++) {
                const s = input.safe[sIdx];
                if (!s) continue;
                if (Math.hypot(cx - s.x, cz - s.z) < s.r) {
                  insideSafe = true;
                  break;
                }
              }
              if (insideSafe) continue;

              if (!spec.flies && input.walkable && !input.walkable(cx, cz)) continue;

              spawnX = cx;
              spawnZ = cz;
              found = true;
              break;
            }
          }
        }

        if (found || spec.flies) {
          const mobId = nextId++;
          newMobs.push({
            id: mobId,
            kind,
            leak: leak.id,
            hp: spec.hp,
            phase: 'roam',
            phaseT: 0,
            provoked: false,
            x: spawnX,
            z: spawnZ,
          });
          livingMobsCount++;
          events.push({ t: 'spawn', mob: mobId, leak: leak.id });
        }
      }
    }
  }

  // The sanctuary (P0-MON-03): a player inside a safe circle is never targeted, and no bolt enters one.
  const inSafe = (x: number, z: number): boolean => {
    for (let sIdx = 0; sIdx < input.safe.length; sIdx++) {
      const s = input.safe[sIdx];
      if (s && Math.hypot(x - s.x, z - s.z) < s.r) return true;
    }
    return false;
  };
  const playerSafe = inSafe(input.player.x, input.player.z);

  // 3. Update Existing Mobs
  const allMobs: Mob[] = [];
  const newBolts: Bolt[] = [];

  for (let i = 0; i < w.mobs.length; i++) {
    const m = w.mobs[i];
    if (!m) continue;
    const spec = ARCHETYPES[m.kind];

    if (m.phase === 'dead') {
      const pt = m.phaseT + dt;
      if (pt < 2.0) {
        allMobs.push({
          ...m,
          phaseT: pt,
        });
      }
      continue;
    }

    if (m.phase === 'pain') {
      const pt = m.phaseT + dt;
      if (pt >= 0.25) {
        allMobs.push({
          ...m,
          phase: 'chase',
          phaseT: 0,
        });
      } else {
        allMobs.push({
          ...m,
          phaseT: pt,
        });
      }
      continue;
    }

    if (m.phase === 'recover') {
      const pt = m.phaseT + dt;
      if (pt >= 0.6) {
        allMobs.push({
          ...m,
          phase: 'chase',
          phaseT: 0,
        });
      } else {
        allMobs.push({
          ...m,
          phaseT: pt,
        });
      }
      continue;
    }

    if (m.phase === 'windup') {
      const pt = m.phaseT + dt;
      if (pt >= spec.windup) {
        if (spec.ranged) {
          const tx = m.targetX ?? input.player.x;
          const tz = m.targetZ ?? input.player.z;
          const dx = tx - m.x;
          const dz = tz - m.z;
          const dist = Math.hypot(dx, dz) || 1;
          const vx = (dx / dist) * 12;
          const vz = (dz / dist) * 12;

          newBolts.push({
            id: nextId++,
            from: m.id,
            x: m.x,
            z: m.z,
            vx,
            vz,
            life: 3.0,
            damage: spec.damage,
          });
        } else {
          const curDist = Math.hypot(input.player.x - m.x, input.player.z - m.z);
          if (input.player.alive && !playerSafe && curDist <= spec.reach + 0.5) {
            events.push({ t: 'hitPlayer', mob: m.id, damage: spec.damage });
          }
        }

        allMobs.push({
          ...m,
          phase: 'recover',
          phaseT: 0,
          targetX: undefined,
          targetZ: undefined,
        });
      } else {
        allMobs.push({
          ...m,
          phaseT: pt,
        });
      }
      continue;
    }

    // Phase: roam or chase or attack
    let leakX = m.x;
    let leakZ = m.z;
    for (let lIdx = 0; lIdx < updatedLeaks.length; lIdx++) {
      const lk = updatedLeaks[lIdx];
      if (lk && lk.id === m.leak) {
        leakX = lk.x;
        leakZ = lk.z;
        break;
      }
    }

    let shouldChase = false;
    let targetX = leakX;
    let targetZ = leakZ;
    let isTargetingMachine = false;
    let nearestMachineId: number | null = null;
    let nearestMachineHu = 0;

    if (spec.targets === 'machine') {
      isTargetingMachine = true;
      // the nearest machine by the gap to its footprint's edge (its centre when it has no footprint)
      let closestDist = Infinity;
      for (let mi = 0; mi < input.machines.length; mi++) {
        const mc = input.machines[mi];
        if (!mc) continue;
        const hu = mc.hu ?? 0;
        const d = Math.max(0, Math.hypot(mc.x - m.x, mc.z - m.z) - hu);
        if (d < closestDist) {
          closestDist = d;
          targetX = mc.x;
          targetZ = mc.z;
          nearestMachineId = mc.id;
          nearestMachineHu = hu;
        }
      }
      if (nearestMachineId !== null) {
        shouldChase = true;
      }
    } else {
      const playerDist = Math.hypot(input.player.x - m.x, input.player.z - m.z);
      if (input.player.alive) {
        if (input.aggression === 'calm') {
          shouldChase = m.provoked;
        } else if (input.aggression === 'normal' || input.aggression === 'hard') {
          shouldChase = m.provoked || playerDist <= 40;
        }
      }
      if (shouldChase) {
        targetX = input.player.x;
        targetZ = input.player.z;
      }
    }

    const distToTarget = Math.hypot(targetX - m.x, targetZ - m.z);
    // a sapper's reach is measured to the machine's footprint edge (the gap), so it drains from outside the pad
    const machineGap = Math.max(0, distToTarget - nearestMachineHu);

    if (isTargetingMachine && nearestMachineId !== null && machineGap <= spec.reach) {
      events.push({
        t: 'drain',
        mob: m.id,
        machine: nearestMachineId,
        amount: spec.damage * dt,
      });
      allMobs.push({
        ...m,
        phase: 'attack',
        phaseT: m.phaseT + dt,
      });
      continue;
    }

    if (!isTargetingMachine && shouldChase && distToTarget <= spec.reach && !playerSafe) {
      events.push({ t: 'telegraph', mob: m.id });
      allMobs.push({
        ...m,
        phase: 'windup',
        phaseT: 0,
        targetX: input.player.x,
        targetZ: input.player.z,
      });
      continue;
    }

    // Move towards target
    const currentPhase: Phase = shouldChase ? 'chase' : 'roam';
    let moveTargetX = targetX;
    let moveTargetZ = targetZ;

    if (!shouldChase) {
      const dLeak = Math.hypot(m.x - leakX, m.z - leakZ);
      if (dLeak > 14) {
        moveTargetX = leakX;
        moveTargetZ = leakZ;
      } else {
        const th = (m.id * 1.618033 + curT * 0.3) % (Math.PI * 2);
        moveTargetX = leakX + Math.cos(th) * 7;
        moveTargetZ = leakZ + Math.sin(th) * 7;
      }
    }

    const mdx = moveTargetX - m.x;
    const mdz = moveTargetZ - m.z;
    const moveDist = Math.hypot(mdx, mdz);

    if (moveDist < 0.05) {
      allMobs.push({
        ...m,
        phase: currentPhase,
      });
      continue;
    }

    const moveSpeed = shouldChase ? spec.speed : spec.speed * 0.5;
    const stepLen = Math.min(moveDist, moveSpeed * dt);
    const baseAngle = Math.atan2(mdz, mdx);

    let nextX = m.x;
    let nextZ = m.z;

    if (spec.flies) {
      const candX = m.x + Math.cos(baseAngle) * stepLen;
      const candZ = m.z + Math.sin(baseAngle) * stepLen;
      const clamped = clampOutsideSafe(candX, candZ, input.safe);
      nextX = clamped.x;
      nextZ = clamped.z;
    } else {
      const solidsList = input.solids ?? [];
      let steerAngle = baseAngle;
      if (solidsList.length > 0 || input.nav) {
        const wp = nextWaypointAroundWalls(
          { x: m.x, z: m.z },
          { x: moveTargetX, z: moveTargetZ },
          solidsList,
          spec.radius,
          input.nav,
        );
        const wdx = wp.x - m.x;
        const wdz = wp.z - m.z;
        if (Math.hypot(wdx, wdz) > 1e-4) {
          steerAngle = Math.atan2(wdz, wdx);
        }
      }
      const stepped = steerGround(m.x, m.z, steerAngle, stepLen, input.safe, input.walkable, solidsList, spec.radius);
      nextX = stepped.x;
      nextZ = stepped.z;
    }

    allMobs.push({
      ...m,
      x: nextX,
      z: nextZ,
      phase: currentPhase,
    });
  }

  // Include freshly spawned mobs
  for (let sIdx = 0; sIdx < newMobs.length; sIdx++) {
    const sm = newMobs[sIdx];
    if (sm) allMobs.push(sm);
  }

  // 4. Monster Separation
  for (let i = 0; i < allMobs.length; i++) {
    const mi = allMobs[i];
    if (!mi || mi.phase === 'dead') continue;
    const specI = ARCHETYPES[mi.kind];

    for (let j = i + 1; j < allMobs.length; j++) {
      const mj = allMobs[j];
      if (!mj || mj.phase === 'dead') continue;
      const specJ = ARCHETYPES[mj.kind];

      const dx = mj.x - mi.x;
      const dz = mj.z - mi.z;
      const dist = Math.hypot(dx, dz);
      const minDist = specI.radius + specJ.radius;

      if (dist < minDist && dist > 1e-5) {
        const overlap = minDist - dist;
        const pushX = (dx / dist) * (overlap * 0.5);
        const pushZ = (dz / dist) * (overlap * 0.5);

        let nIx = mi.x - pushX;
        let nIz = mi.z - pushZ;
        let nJx = mj.x + pushX;
        let nJz = mj.z + pushZ;

        const clI = clampOutsideSafe(nIx, nIz, input.safe);
        if (isValidPosition(clI.x, clI.z, specI.flies, input.safe, input.walkable)) {
          allMobs[i] = { ...mi, x: clI.x, z: clI.z };
        }

        const clJ = clampOutsideSafe(nJx, nJz, input.safe);
        if (isValidPosition(clJ.x, clJ.z, specJ.flies, input.safe, input.walkable)) {
          allMobs[j] = { ...mj, x: clJ.x, z: clJ.z };
        }
      }
    }
  }

  // 4b. Ground monsters keep out of the built footprints: a wall built over one, or a separation push, moves it to the
  // nearest edge (P0-MON-03). Flyers pass over.
  const solids = input.solids ?? [];
  if (solids.length > 0) {
    for (let i = 0; i < allMobs.length; i++) {
      const mi = allMobs[i];
      if (!mi || mi.phase === 'dead' || ARCHETYPES[mi.kind].flies) continue;
      const out = pushOutOfSolids(mi.x, mi.z, ARCHETYPES[mi.kind].radius, solids);
      if (out.x !== mi.x || out.z !== mi.z) allMobs[i] = { ...mi, x: out.x, z: out.z };
    }
  }

  // 5. Update Bolts
  const activeBolts: Bolt[] = [];
  const boltsToProcess = [...w.bolts, ...newBolts];

  for (let bIdx = 0; bIdx < boltsToProcess.length; bIdx++) {
    const b = boltsToProcess[bIdx];
    if (!b) continue;

    const remainingLife = b.life - dt;
    if (remainingLife <= 0) continue;

    const bx = b.x + b.vx * dt;
    const bz = b.z + b.vz * dt;

    // a bolt breaks on the dome's edge: it never flies in, and never hits anyone inside
    if (inSafe(bx, bz)) continue;

    // POL-33: a bolt breaks when its segment hits a built wall or solid footprint
    if (solids.length > 0 && boltBlockedBySolids(b.x, b.z, bx, bz, solids).blocked) continue;

    if (input.player.alive && Math.hypot(bx - input.player.x, bz - input.player.z) <= 0.6) {
      events.push({ t: 'hitPlayer', mob: b.from, damage: b.damage });
      continue;
    }

    activeBolts.push({
      id: b.id,
      from: b.from,
      x: bx,
      z: bz,
      vx: b.vx,
      vz: b.vz,
      life: remainingLife,
      damage: b.damage,
    });
  }

  return {
    world: {
      t: nextT,
      rng: curRng,
      nextId,
      mobs: allMobs,
      bolts: activeBolts,
      leaks: updatedLeaks,
    },
    events,
  };
}

export function hurt(
  w: World,
  mobId: number,
  damage: number
): { readonly world: World; readonly events: readonly Event[] } {
  const events: Event[] = [];
  let found = false;

  const nextMobs: Mob[] = [];

  for (let i = 0; i < w.mobs.length; i++) {
    const m = w.mobs[i];
    if (!m) continue;

    if (m.id !== mobId || m.phase === 'dead') {
      nextMobs.push(m);
      continue;
    }

    found = true;
    const newHp = m.hp - damage;
    const spec = ARCHETYPES[m.kind];

    if (newHp <= 0) {
      events.push({ t: 'death', mob: m.id, drop: spec.drop });
      nextMobs.push({
        ...m,
        hp: 0,
        phase: 'dead',
        phaseT: 0,
        provoked: true,
      });
    } else {
      const nextPhase: Phase = m.kind === 'brute' ? m.phase : 'pain';
      nextMobs.push({
        ...m,
        hp: newHp,
        phase: nextPhase,
        phaseT: m.kind === 'brute' ? m.phaseT : 0,
        provoked: true,
      });
    }
  }

  if (!found) {
    return { world: w, events: [] };
  }

  return {
    world: {
      t: w.t,
      rng: w.rng,
      nextId: w.nextId,
      mobs: nextMobs,
      bolts: w.bolts,
      leaks: w.leaks,
    },
    events,
  };
}

export function raycast(w: World, from: P, dir: P, range: number): number | null {
  const dLen = Math.hypot(dir.x, dir.z);
  if (dLen === 0) return null;
  const dx = dir.x / dLen;
  const dz = dir.z / dLen;

  let nearestId: number | null = null;
  let nearestDist = Infinity;

  for (let i = 0; i < w.mobs.length; i++) {
    const m = w.mobs[i];
    if (!m || m.phase === 'dead') continue;

    const r = ARCHETYPES[m.kind].radius;
    const vx = m.x - from.x;
    const vz = m.z - from.z;

    const tProj = vx * dx + vz * dz;
    const dPerpSq = vx * vx + vz * vz - tProj * tProj;
    const rSq = r * r;

    if (dPerpSq > rSq) continue;

    const delta = Math.sqrt(Math.max(0, rSq - dPerpSq));
    const tHit = vx * vx + vz * vz <= rSq ? 0 : tProj - delta;

    if (tHit >= 0 && tHit <= range && tHit < nearestDist) {
      nearestDist = tHit;
      nearestId = m.id;
    }
  }

  return nearestId;
}

export function encode(w: World): string {
  return JSON.stringify(w);
}

export function decode(s: string): World {
  const parsed = JSON.parse(s) as World;
  return {
    t: parsed.t,
    rng: parsed.rng,
    nextId: parsed.nextId,
    mobs: parsed.mobs.map((m) => ({
      id: m.id,
      kind: m.kind,
      leak: m.leak,
      hp: m.hp,
      phase: m.phase,
      phaseT: m.phaseT,
      provoked: m.provoked,
      x: m.x,
      z: m.z,
      ...(m.targetX !== undefined ? { targetX: m.targetX } : {}),
      ...(m.targetZ !== undefined ? { targetZ: m.targetZ } : {}),
    })),
    bolts: parsed.bolts.map((b) => ({
      id: b.id,
      from: b.from,
      x: b.x,
      z: b.z,
      vx: b.vx,
      vz: b.vz,
      life: b.life,
      damage: b.damage,
    })),
    // the same key order as addLeak, so encode(decode(s)) === s (landing fix: it was id, kinds, ..., x, z)
    leaks: parsed.leaks.map((l) => ({
      id: l.id,
      x: l.x,
      z: l.z,
      kinds: [...l.kinds],
      seal: l.seal,
      sealed: l.sealed,
      nextWave: l.nextWave,
    })),
  };
}

/**
 * A monster placed by hand (the tests and the dev hooks): a mob of `kind` at `at`, on no leak (`leak` -1: it roams where it stands).
 * Deterministic: the id is the world's next id, and the world's clock and random state are untouched.
 */
export function placeMob(w: World, kind: Archetype, at: P): World {
  const id = w.nextId;
  const spec = ARCHETYPES[kind];
  const mob: Mob = { id, kind, leak: -1, hp: spec.hp, phase: 'roam', phaseT: 0, provoked: false, x: at.x, z: at.z };
  return { t: w.t, rng: w.rng, nextId: id + 1, mobs: [...w.mobs, mob], bolts: w.bolts, leaks: w.leaks };
}

